class CoreCommands:
    def get(self, name):
        return self.execute_command("GET", name)

    def set(self, name, value, *args, **kwargs):
        return self.execute_command("SET", name, value)

    def eval(self, script, numkeys, *keys_and_args):
        return self.execute_command("EVAL", script, numkeys, *keys_and_args)

    def execute_command(self, *args, **kwargs):
        pass

class AsyncCoreCommands:
    async def get(self, name):
        return await self.execute_command("GET", name)

    async def set(self, name, value, *args, **kwargs):
        return await self.execute_command("SET", name, value)

    async def eval(self, script, numkeys, *keys_and_args):
        return await self.execute_command("EVAL", script, numkeys, *keys_and_args)

    async def execute_command(self, *args, **kwargs):
        pass
